struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    constexpr int warpWidth = 32;
    const unsigned int warpMask = 0xffffffffu;
    const long long particleCount = static_cast<long long>(n);

    const long long globalIndex =
        static_cast<long long>(blockIdx.x) * static_cast<long long>(blockDim.x) +
        static_cast<long long>(threadIdx.x);
    const bool targetValid = globalIndex < particleCount;
    const int i = targetValid ? static_cast<int>(globalIndex) : 0;

    Particle p;
    if (targetValid) {
        p = in[i];
    }

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    const int lane = static_cast<int>(threadIdx.x) & (warpWidth - 1);

    // Load the first tile, then pre-load the next tile before processing the current one.
    float sourceX = 0.0f;
    float sourceY = 0.0f;
    float sourceZ = 0.0f;
    float sourceMass = 0.0f;
    const long long firstSourceIndex = lane;
    if (firstSourceIndex < particleCount) {
        const Particle& source = in[static_cast<int>(firstSourceIndex)];
        sourceX = source.x;
        sourceY = source.y;
        sourceZ = source.z;
        sourceMass = source.mass;
    }

    for (long long tileBase = 0; tileBase < particleCount; tileBase += warpWidth) {
        float nextX = 0.0f;
        float nextY = 0.0f;
        float nextZ = 0.0f;
        float nextMass = 0.0f;

        const long long nextSourceIndex = tileBase + warpWidth + lane;
        if (nextSourceIndex < particleCount) {
            const Particle& nextSource = in[static_cast<int>(nextSourceIndex)];
            nextX = nextSource.x;
            nextY = nextSource.y;
            nextZ = nextSource.z;
            nextMass = nextSource.mass;
        }

        // The bound check is uniform across the warp; every lane reaches each shuffle.
        #pragma unroll
        for (int sourceLane = 0; sourceLane < warpWidth; ++sourceLane) {
            const long long sourceJ = tileBase + sourceLane;
            if (sourceJ >= particleCount) {
                break;
            }

            const float xj = __shfl_sync(warpMask, sourceX, sourceLane);
            const float yj = __shfl_sync(warpMask, sourceY, sourceLane);
            const float zj = __shfl_sync(warpMask, sourceZ, sourceLane);
            const float massJ = __shfl_sync(warpMask, sourceMass, sourceLane);

            if (targetValid && i != sourceJ) {
                const float dx = xj - p.x;
                const float dy = yj - p.y;
                const float dz = zj - p.z;

                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * p.mass * massJ) / (distSq * dist);

                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }

        sourceX = nextX;
        sourceY = nextY;
        sourceZ = nextZ;
        sourceMass = nextMass;
    }

    if (targetValid) {
        p.vx += (fx / p.mass) * dt;
        p.vy += (fy / p.mass) * dt;
        p.vz += (fz / p.mass) * dt;

        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.z += p.vz * dt;

        out[i] = p;
    }
}
